/**
 * Iterating over the configuration while another thread is modifying it
 * must not fail with a {@link ConcurrentModificationException}, see
 * HADOOP-13500.
 */
@Test
public void testConcurrentModificationDuringIteration() throws Exception {
  final Configuration config = new Configuration();
  final AtomicBoolean done = new AtomicBoolean(false);
  final AtomicBoolean exceptionOccurred = new AtomicBoolean(false);

  Thread iteratingThread = new Thread(new Runnable() {
    @Override
    public void run() {
      while (!done.get()) {
        try {
          config.iterator();
        } catch (ConcurrentModificationException e) {
          exceptionOccurred.set(true);
          return;
        }
      }
    }
  });
  iteratingThread.start();

  try {
    for (int i = 0; i < 50000 && !exceptionOccurred.get(); i++) {
      config.set("concurrent.modification.property-" + i, "value");
    }
  } finally {
    done.set(true);
    iteratingThread.join();
  }

  assertFalse("ConcurrentModificationException occurred",
      exceptionOccurred.get());
}

